CREATE TABLE IF NOT EXISTS piano_weeks (
 id INTEGER PRIMARY KEY AUTOINCREMENT, label TEXT NOT NULL, lesson_date TEXT NOT NULL DEFAULT '', teacher_note TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS piano_tasks (
 id INTEGER PRIMARY KEY AUTOINCREMENT, week_id INTEGER NOT NULL REFERENCES piano_weeks(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('technique','piece','sight-reading','theory')), title TEXT NOT NULL, range_label TEXT NOT NULL DEFAULT '', goal TEXT NOT NULL DEFAULT '', priority INTEGER NOT NULL DEFAULT 2 CHECK(priority BETWEEN 1 AND 3), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','done','paused')), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS piano_assets (
 id INTEGER PRIMARY KEY AUTOINCREMENT, week_id INTEGER NOT NULL REFERENCES piano_weeks(id) ON DELETE CASCADE, task_id INTEGER REFERENCES piano_tasks(id) ON DELETE SET NULL, kind TEXT NOT NULL CHECK(kind IN ('assignment','feedback')), source_path TEXT NOT NULL, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, ocr_text TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS piano_sessions (
 id INTEGER PRIMARY KEY AUTOINCREMENT, week_id INTEGER NOT NULL REFERENCES piano_weeks(id) ON DELETE CASCADE, task_id INTEGER REFERENCES piano_tasks(id) ON DELETE SET NULL, practiced_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, minutes INTEGER NOT NULL DEFAULT 25 CHECK(minutes BETWEEN 1 AND 90), self_status TEXT NOT NULL CHECK(self_status IN ('smooth','practising','stuck')), difficulty_note TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS piano_feedback (
 id INTEGER PRIMARY KEY AUTOINCREMENT, week_id INTEGER NOT NULL REFERENCES piano_weeks(id) ON DELETE CASCADE, task_id INTEGER REFERENCES piano_tasks(id) ON DELETE SET NULL, asset_id INTEGER REFERENCES piano_assets(id) ON DELETE SET NULL, note TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_piano_tasks_week ON piano_tasks(week_id,priority DESC);
